class_name QuizAudioFeedback
extends Node

@export var correct_sound: AudioStream
@export var wrong_sound: AudioStream
@export var volume_balance_db: float = 0.0

@onready var _audio_player: AudioStreamPlayer = $AudioPlayer


func play_feedback(is_correct: bool) -> void:
	if is_correct:
		_audio_player.stream = correct_sound
	else:
		_audio_player.stream = wrong_sound
	_audio_player.volume_db = volume_balance_db
	_audio_player.play()


func stop_feedback() -> void:
	_audio_player.stop()


func is_feedback_playing() -> bool:
	return _audio_player.playing

class_name QuizMusicPlayer
extends Node

@export var music_stream: AudioStream = preload("res://assets/audio/music_loop.wav")
@export var auto_start: bool = true

@onready var _music_player: AudioStreamPlayer = $MusicPlayer


func _ready() -> void:
	if auto_start and music_stream != null:
		play_music()


func prepare_loop() -> void:
	if music_stream is AudioStreamWAV:
		var wav_stream: AudioStreamWAV = music_stream as AudioStreamWAV
		wav_stream.loop_mode = AudioStreamWAV.LOOP_FORWARD


func play_music(from_position: float = 0.0) -> void:
	prepare_loop()
	if _music_player.stream != music_stream:
		_music_player.stream = music_stream
	_music_player.play(from_position)


func stop_music() -> void:
	_music_player.stop()


func is_music_playing() -> bool:
	return _music_player.playing

class_name QuizAudioController
extends Node

@export var click_volume_db: float = -4.0
@export var min_pitch: float = 0.95
@export var max_pitch: float = 1.05

@onready var feedback: QuizAudioFeedback = $Feedback
@onready var music: QuizMusicPlayer = $Music
@onready var click_player: AudioStreamPlayer = $ClickPlayer


func play_click() -> void:
	var random_pitch: float = randf_range(min_pitch, max_pitch)
	click_player.pitch_scale = random_pitch
	click_player.volume_db = click_volume_db
	click_player.play()


func play_answer_feedback(is_correct: bool) -> void:
	feedback.play_feedback(is_correct)


func start_bg_music() -> void:
	music.play_music()


func stop_bg_music() -> void:
	music.stop_music()


func is_click_playing() -> bool:
	return click_player.playing

